import 'package:flutter_test/flutter_test.dart';import 'package:likerts/advanced_questions.dart';
import 'package:likerts/likerts.dart';import 'package:likerts/survey.dart';import 'package:flutter/material.dart';
void main(){test('mobile-safe advanced mutations and validation',(){expect(moveRanking(['a','b','c'],'b',-1),['b','a','c']);var matrix=setMatrixChoice({},'r1','c1',multiple:true);matrix=setMatrixChoice(matrix,'r1','c2',multiple:true);expect(matrix,{'r1':['c1','c2']});expect(validRanking(['c','a','b'],['a','b','c']),isTrue);expect(validRanking(['a','a','b'],['a','b','c']),isFalse);expect(validMatrix({'r1':['c1']},['r1'],['c1','c2'],multiple:false,required:true),isTrue);expect(validAllocation({'a':50,'b':50},['a','b'],100),isTrue);expect(allocationRemaining(100,{'a':25,'b':50}),25);});testWidgets('stacked controls emit exact v5 answers',(tester)async{final collection=Collection.fromJson({'id':'c','surveyId':'s','version':1,'placement':'p','schema':{'schemaVersion':5,'title':'Advanced','questions':[{'id':'rank','type':'ranking','label':'Rank','required':true,'options':[{'id':'a','label':'A'},{'id':'b','label':'B'}]},{'id':'matrix','type':'matrix','label':'Matrix','required':true,'matrixMode':'single','rows':[{'id':'r','label':'Row'}],'columns':[{'id':'c1','label':'One'},{'id':'c2','label':'Two'}]},{'id':'sum','type':'constant_sum','label':'Allocate','required':true,'total':100,'items':[{'id':'x','label':'X'},{'id':'y','label':'Y'}]}]}});Map<String,dynamic>? submitted;await tester.pumpWidget(MaterialApp(home:Scaffold(body:LikertsSurvey(collection:collection,onSubmit:(value)=>submitted=value))));await tester.tap(find.text('Move down').first);await tester.tap(find.byKey(const ValueKey('likerts.matrix.matrix.r.c2')));await tester.enterText(find.byKey(const ValueKey('c:1:sum:x')),'60');await tester.enterText(find.byKey(const ValueKey('c:1:sum:y')),'40');final submit=find.byKey(const ValueKey('likerts.submit'));await tester.ensureVisible(submit);await tester.tap(submit);await tester.pump();expect(submitted,{'rank':['b','a'],'matrix':{'r':'c2'},'sum':{'x':60,'y':40}});});}
